import {Physics,Ragdoll,dist,clamp,seeded} from './premium-utils.js';
export const BUDDY_GADGETS=[['grab','Grab & fling',0],['glove','Boxing glove',0],['spring','Spring launcher',0],['ball','Bouncy ball',0],['water','Water balloon',0],['confetti','Confetti burst',15],['foam','Foam blaster',20],['fan','Fan',25],['magnet','Giant magnet',30],['slime','Slime splat',35],['rocket','Cartoon rocket',40],['bubble','Bubble machine',45],['trampoline','Trampoline',50],['gravity','Gravity switch',55],['inflatable','Inflatable obstacle',60]].map(([id,name,cost])=>({id,name,cost}));
export const BUDDY_ROOMS=[['Padded Playroom',1,.015],['Space Station',.13,.01],['Candy Factory',.85,.018],['Pinball Arena',1.1,.005],['Bouncy Castle',.8,.01],['Underwater Room',-.07,.075],['Low Gravity Lab',.3,.012],['Cartoon Construction',1.2,.025]].map(([name,gravity,drag],i)=>({id:i,name,gravity,drag}));
export class BuddyModel{
 constructor({difficulty=3,mode='launch',seed=42,level=1,room=0,unlocks=[]}={}){this.kind='buddy';this.difficulty=difficulty;this.mode=mode;this.levelId=level;this.seed=seed;this.rng=seeded(seed);this.room=BUDDY_ROOMS[room];this.physics=new Physics(this.room.gravity);this.physics.bounds();this.doll=new Ragdoll(this.physics,370,330,1.7,{neck:true});this.doll.parts.forEach(b=>b.frictionAir=this.room.drag);this.tool='grab';this.phase='play';this.clock=0;this.duration=mode==='sandbox'?Infinity:mode==='puzzle'?90000:60000;this.done=false;this.complete=false;this.hits=0;this.mistakes=0;this.combo=0;this.bestCombo=0;this.points=0;this.used=new Set();this.unlocked=new Set(['grab','glove','spring','ball','water',...(mode==='target'?['foam']:mode==='combo'?['confetti','foam','fan']:[]),...unlocks]);this.gadgets=[];this.events=[];this.particles=[];this.lastImpact=-1000;this.nextGadget=0;this.interactions=0;this.expression='curious';this.expressionUntil=0;this.targets=Array.from({length:mode==='puzzle'?3:5},(_,i)=>({x:630+(i%2)*150+this.rng()*55,y:115+i*88+this.rng()*25,r:[53,47,41,36,30][difficulty-1],hit:false}));if(room===2||room===7)this.physics.rect(750,495,180,22,{isStatic:true,angle:room===2?-.2:.2});if(room===3||room===4){this.physics.circle(170,360,55,{isStatic:true,restitution:1.2});this.physics.circle(820,340,55,{isStatic:true,restitution:1.2});}this.collide=e=>{for(const pair of e.pairs){if(!this.doll.parts.includes(pair.bodyA)&&!this.doll.parts.includes(pair.bodyB))continue;const speed=Math.max(pair.bodyA.speed,pair.bodyB.speed);if(speed>2&&this.clock-this.lastImpact>180){this.lastImpact=this.clock;this.combo=this.clock-(this.lastBounce||0)<1800?this.combo+1:1;this.lastBounce=this.clock;this.bestCombo=Math.max(this.bestCombo,this.combo);this.points+=Math.round(speed*3)*Math.min(6,this.combo);this.expression='dizzy';this.expressionUntil=this.clock+850;this.events.push('boing');}}};this.physics.M.Events.on(this.physics.engine,'collisionStart',this.collide);this.feedback='Meet Pogo: a stitched star pilot. Grab a limb and fling, or experiment with a gadget.';}
 input(kind,x,y,id){if(this.done)return false;if(this.tool==='grab'){if(kind==='down'){const grabbed=this.doll.grab(id,x,y);if(grabbed)this.interactions++;return grabbed;}if(kind==='move'){this.doll.move(id,x,y);return true;}if(kind==='up'||kind==='cancel')return this.doll.release(id,kind==='cancel');}if(kind==='down')return this.gadget(this.tool,x,y);return false;}
 gadget(id,x,y){if(!this.unlocked.has(id)){this.feedback='Earn coins in challenges, then unlock this gadget in the collection.';return false;}if(this.clock<this.nextGadget)return false;this.nextGadget=this.clock+[220,300,400,500,600][this.difficulty-1];const M=this.physics.M,c=this.doll.torso.position,dx=c.x-x,dy=c.y-y,n=Math.hypot(dx,dy)||1;this.used.add(id);this.interactions++;this.expression='surprised';this.expressionUntil=this.clock+1000;this.events.push('gadget');this.feedback=BUDDY_GADGETS.find(g=>g.id===id)?.name+' activated!';
 if(id==='glove'){this.doll.impulse(dx/n*.03,dy/n*.03);this.gadgets.push({id,x,y,until:this.clock+300});}
 if(id==='spring'){this.doll.impulse(.003,-.055);this.gadgets.push({id,x:c.x,y:600,until:this.clock+450});}
 if(id==='ball'||id==='foam'||id==='water'){const origin=id==='foam'&&this.mode==='target'?{x:120,y:560}:{x,y:Math.min(y,560)};const b=this.physics.circle(origin.x,origin.y,id==='ball'?28:id==='water'?23:15,{restitution:id==='ball'?1.15:.7,density:.003,frictionAir:id==='foam'?0:.01});if(id==='foam'&&this.mode==='target'){const flight=1.1;M.Body.setVelocity(b,{x:(x-origin.x)/flight/60,y:(y-origin.y-.5*this.room.gravity*1000*flight*flight)/flight/60});}else M.Body.setVelocity(b,{x:dx/n*11,y:dy/n*11});this.gadgets.push({id,body:b,until:this.clock+6500});if(id==='water'){this.wetUntil=this.clock+2800;this.doll.parts.forEach(p=>p.frictionAir=.06);}}
 if(id==='confetti'){this.doll.impulse(dx/n*.018,-.025);for(let i=0;i<28;i++)this.particles.push({x,y,vx:Math.cos(i)*130,vy:Math.sin(i)*130,life:1800});}
 if(id==='fan'||id==='magnet'){this.gadgets.push({id,x,y,until:this.clock+6500});}
 if(id==='slime'){this.stickyUntil=this.clock+2500;this.doll.parts.forEach(p=>p.frictionAir=.18);}
 if(id==='rocket'){this.rocketUntil=this.clock+1800;this.rocketDirection={x:dx/n*.003,y:dy/n*.003-.002};}
 if(id==='bubble'){this.bubbleUntil=this.clock+3800;this.doll.impulse(0,-.025);}
 if(id==='trampoline'||id==='inflatable'){const b=id==='trampoline'?this.physics.rect(x,clamp(y,150,590),180,22,{isStatic:true,restitution:1.4}):this.physics.circle(x,clamp(y,90,530),65,{isStatic:true,restitution:1.1});this.gadgets.push({id,body:b,until:this.clock+12000});}
 if(id==='gravity'){this.physics.engine.gravity.y=this.physics.engine.gravity.y>0?-.65:this.room.gravity||1;}
 if(this.gadgets.length>24){const g=this.gadgets.shift();if(g.body)this.physics.remove(g.body);}return true;}
 action(id){if(id==='finish'&&this.mode==='sandbox'){this.done=true;return true;}return false;}
 update(dt){if(this.done)return;this.physics.tick(dt,t=>{this.clock+=t;const c=this.doll.torso.position;if(this.clock>this.expressionUntil)this.expression='curious';if(this.clock>Math.max(this.wetUntil||0,this.stickyUntil||0))this.doll.parts.forEach(p=>p.frictionAir=this.room.drag);for(const g of this.gadgets){if(g.id==='fan'&&dist(g,c)<300)this.doll.impulse(.0009,-.00065);if(g.id==='magnet'){const dx=g.x-c.x,dy=g.y-c.y,n=Math.hypot(dx,dy)||1;if(n<350)this.doll.impulse(dx/n*.0008,dy/n*.0008);}}if(this.clock<this.rocketUntil)this.doll.impulse(this.rocketDirection.x,this.rocketDirection.y);if(this.clock<this.bubbleUntil)this.doll.impulse(0,-.0011);for(const target of this.targets){const ty=this.mode==='target'?target.y+Math.sin(this.clock/1000+target.x)*35:target.y;if(!target.hit&&(this.mode==='target'?this.gadgets.some(g=>g.body&&['foam','ball','water'].includes(g.id)&&dist(g.body.position,{x:target.x,y:ty})<target.r+15):!this.doll.grabs.size&&this.doll.parts.some(p=>dist(p.position,{x:target.x,y:ty})<target.r+20))){target.hit=true;this.hits++;this.points+=300;this.events.push('target');this.expression='happy';this.expressionUntil=this.clock+1800;}}
 for(const g of this.gadgets)if(g.body&&this.clock>=g.until)this.physics.remove(g.body);this.gadgets=this.gadgets.filter(g=>this.clock<g.until);this.particles=this.particles.filter(p=>{p.x+=p.vx*t/1000;p.y+=p.vy*t/1000;p.life-=t;return p.life>0;});const objective=this.mode==='bounce'?this.bestCombo>=8:this.mode==='combo'?this.used.size>=6&&this.hits>=2:this.mode==='puzzle'?this.hits===this.targets.length&&this.used.size>=2:this.hits===this.targets.length;if(objective&&this.mode!=='sandbox'){this.complete=this.done=true;this.events.push('finish');}if(this.clock>=this.duration)this.done=true;});}
 cancel(){this.doll.cancel();}dispose(){this.doll.cancel();this.physics.dispose();}get score(){return Math.max(0,this.points+(this.complete?600:0)+this.used.size*30);}get coins(){return this.mode==='sandbox'?0:Math.min(60,5+Math.floor(this.score/100));}summary(){return{completed:this.complete,targets:this.hits,bestCombo:this.bestCombo,gadgets:[...this.used],coins:this.coins,interactions:this.interactions};}
}
